import{az as a,P as o,Q as t,aQ as c}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/react/index.md","filePath":"面试题/react/index.md","lastUpdated":1746243530000}'),r={name:"面试题/react/index.md"};function d(n,e,l,i,p,s){return o(),t("div",null,[...e[0]||(e[0]=[c('<h2 id="为什么setstate设计成异步" tabindex="-1">为什么<code>setState</code>设计成异步 <a class="header-anchor" href="#为什么setstate设计成异步" aria-label="Permalink to “为什么setState设计成异步”">​</a></h2><ol><li>将所有的setState集中批量更新，将最终的数据返回调用render，避免<a href="/page__blog-doc/js/runtime/event-loop">同步</a>调用频繁的更新数据触发视图渲染</li><li>同步更新了state但是不能确保props保持一致性。</li></ol><h2 id="react-component-和-react-purecomponent-的区别" tabindex="-1">React.Component 和 React.PureComponent 的区别 <a class="header-anchor" href="#react-component-和-react-purecomponent-的区别" aria-label="Permalink to “React.Component 和 React.PureComponent 的区别”">​</a></h2><p>默认情况下，每次状态或props发生变化时，<code>React.Component</code>都会进行重新渲染。<br> React.PureComponent是React.Component的一个子类，它在渲染行为上有所不同。<code>React.PureComponent</code>在默认情况下实现了<code>shouldComponentUpdate</code>方法，它通过浅比较组件的<code>props</code>和<code>state</code>来决定是否需要重新渲染。如果<code>props</code>和<code>state</code>都是相同的，组件将不会重新渲染。</p><ol><li>性能优化：<code>React.PureComponent</code>通过浅比较<code>props</code>和<code>state</code>来避免不必要的渲染，这可以提高组件的性能。如果组件的状态和属性在渲染之间没有变化，那么组件将不会重新渲染。</li><li>实现细节：<code>React.PureComponent</code>在内部实现了<code>shouldComponentUpdate</code>方法，而<code>React.Component</code>需要开发者自己实现或继承默认行为（总是返回true）。</li><li>使用场景：当你确定组件的渲染结果只依赖于其<code>props</code>和<code>state</code>，并且这些<code>props</code>和<code>state</code>是可比较的（例如，基本类型或具有稳定引用的对象）</li></ol><h2 id="react组件为什么不能返回多个元素-为什么只能有一个根元素" tabindex="-1">react组件为什么不能返回多个元素，为什么只能有一个根元素 <a class="header-anchor" href="#react组件为什么不能返回多个元素-为什么只能有一个根元素" aria-label="Permalink to “react组件为什么不能返回多个元素，为什么只能有一个根元素”">​</a></h2><p>因为虚拟dom，如果有多个根节点是无法确认在哪个节点上更新的，但是react可以使fragment创建根元素进行包裹，vue也是同样的表示</p><h2 id="react生命周期" tabindex="-1">react生命周期 <a class="header-anchor" href="#react生命周期" aria-label="Permalink to “react生命周期”">​</a></h2><h3 id="挂载" tabindex="-1">挂载 <a class="header-anchor" href="#挂载" aria-label="Permalink to “挂载”">​</a></h3><ol><li>初始化<code>constructor</code></li><li>静态方法,主要用于在组件接收到新的 props 时更新 state <code>static getDerivedStateFromProps</code></li><li>挂载中 生成虚拟DOM <code>render</code></li><li>挂载完毕 <code>componentDidMount</code></li></ol><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h3><p><code>static getDerivedStateFromProps</code> 组件更新前 <code>shouldComponentUpdate</code> 更新虚拟dom <code>render</code> 获取更新前的状态 <code>getSnapshotBeforeUpdate</code> 更新完成 <code>componentDidUpdate</code></p><h3 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to “卸载”">​</a></h3><p>移除组件 <code>componentWillUnMount</code></p><h2 id="常用组件" tabindex="-1">常用组件 <a class="header-anchor" href="#常用组件" aria-label="Permalink to “常用组件”">​</a></h2><h3 id="portal" tabindex="-1">portal <a class="header-anchor" href="#portal" aria-label="Permalink to “portal”">​</a></h3><p>让子组件渲染在除了父组件之外的 dom 节点的方式</p>',17)])])}const P=a(r,[["render",d]]);export{u as __pageData,P as default};
